        parentElement = new Element("root");
        parentElement.setAttribute(new Attribute("attr1", "value1"));
        parentElement.setAttribute(new Attribute("attr2", "value2"));
        parentElement.addContent(new Element("child1"));
        parentElement.addContent(new Element("child2"));

